1	// grow_with_claudinite task: growth-dedup — the growth lifecycle's PRUNING stage
2	// (per-project-scheduling DESIGN §6). Prunes local-pack items the canon now
3	// covers, keeping items the canon states too generally; opens a PR against the
4	// default branch for the owner to approve. Worker: task.md.
5	//
6	// The old fleet's `relevantCanonChanged` becomes the `sharedMount` signal — a
7	// declared pack's vendored files moving is the local echo of "the canon this repo
8	// mounts changed" — and the weekly re-check crutch retires: a quiet repo with no
9	// local packs skips.
10	//
11	// Self-contained (imports nothing): the whole contract is this default export.
12	
13	export default {
14	  id: 'growth-dedup',
15	  frequency: 'daily+1h',           // the 05:00 slot — prunes against the merged/mounted canon, after promote (DESIGN §2)
16	  precondition_signals: ['localPacks', 'sharedMount', 'commits'],
17	  agent_model: 'opus',                   // proving the canon genuinely covers a local item — and telling coverage from "stated too generally" — is a judgment call
18	  expected_outcome: 'open-pr',              // a wrongful prune deletes a real local lesson, so this keeps a HUMAN approval gate (never auto-merge)
19	  agent_instructions: 'task.md',
20	  agent_execution_timeout: 1800,            // proving canon coverage per local item — generous bound, extreme protection
21	
22	  // Gate: the repo must actually track local packs (no local packs → nothing to
23	  // prune, self-skip). Given local packs, run when the mounted canon this repo
24	  // CARES about moved — a declared pack's vendored files changed (`sharedMount`),
25	  // which can newly cover a local item — or the repo's own local packs changed in
26	  // the window (a fresh local item to re-check against the canon). A quiet repo
27	  // with local packs but no relevant movement skips.
28	  precondition(signals) {
29	    const local = signals.localPacks ?? {};
30	    // `present` is null when the scheduler couldn't determine it; treat only an
31	    // explicit false as "definitely no local packs to prune".
32	    if (local.present === false) {
33	      return { run: false, reason: 'no local packs — nothing to prune' };
34	    }
35	    const changedPacks = signals.sharedMount?.changedPacks ?? [];
36	    const canonMoved = changedPacks.length > 0;
37	    const localChanged = local.changedInWindow === true;
38	
39	    if (canonMoved) {
40	      return { run: true, reason: `declared pack(s) changed in the mounted canon: ${changedPacks.join(', ')} — local items may now be covered`, context: [`Re-check local items against these newly-changed canon packs: ${changedPacks.join(', ')}.`] };
41	    }
42	    if (localChanged) {
43	      return { run: true, reason: 'local packs changed in the window — re-check the fresh items against the mounted canon' };
44	    }
45	    return { run: false, reason: 'local packs present but no relevant canon or local movement in the window' };
46	  },
47	};
48

