1	// Due-slot math for the vendored hourly scheduler (per-project-scheduling
2	// DESIGN §3). Pure and stateless: given the repo's `schedule` anchor, the
3	// frequencies its tasks declare, the current time `now`, and the timestamp
4	// `lastSuccess` of the scheduler's last SUCCESSFUL run (read from the Actions
5	// run ledger GitHub already keeps — there is no watermark file to corrupt),
6	// this decides exactly which frequencies are due and the slot id each is
7	// running under.
8	//
9	// The whole model is: consider ONLY the single most-recent scheduled slot per
10	// frequency, and it is due iff its time falls in `(lastSuccess, now]`.
11	//   - Miss / outage self-heals — the next successful run catches up the one
12	//     most-recent daily/weekly/monthly slot; a 3-day outage yields one catch-up
13	//     evaluation per frequency, never a backfill storm (DESIGN §3.1).
14	//   - HOURLY never catches up for free: its most-recent slot is always the
15	//     current hour, so an outage evaluates the current poll once and never a
16	//     stale one — no special case needed, the most-recent-only rule delivers it.
17	//   - Late / early fire is irrelevant: due-ness is schedule math, never
18	//     wall-clock equality with the (hashed :10–:50) cron minute.
19	//   - First run (`lastSuccess` null / fresh adoption) → the most-recent slot of
20	//     the FIRST-RUN SET only (hourly + the daily family): the immediate
21	//     evaluation that smoke-tests a newly-wired repo, without an off-anchor
22	//     weekly/monthly run on it (DESIGN §3.1, #522).
23	//
24	// `lastSuccess` null means exactly one thing — the ledger was read and holds no
25	// successful run. A ledger that could not be READ is never null: the caller
26	// (`lastSuccessTime`) throws, and the run fails rather than reach this math with
27	// a watermark it had to guess (#522).
28	//
29	// All times are UTC (the `schedule` values are UTC by contract, DESIGN §2). This
30	// module never reads the clock itself — `now` is always injected — so the whole
31	// due-ness decision is deterministic and testable.
32	
33	// The seven legal frequency tokens (DESIGN §1). `task-declaration-shape` is what
34	// rejects anything outside this set at author time; here an unknown token is
35	// simply never due (defensive — the scheduler must not throw on a stray value).
36	export const FREQUENCIES = ['hourly', 'daily-2h', 'daily-1h', 'daily', 'daily+1h', 'weekly', 'monthly'];
37	
38	// What a FIRST run (an empty ledger — fresh adoption) evaluates. Deliberately
39	// not every frequency: the first run is an adoption smoke test, and the wiring
40	// it proves — task discovery, signal collection, the dispatch issue, the label,
41	// executor pickup — is identical whatever the frequency, so the daily family
42	// exercises all of it. Including weekly and monthly would only add an
43	// off-anchor run of their unconditional tasks (open-web research, pack
44	// discovery, the fleet sweep) on the least-proven repo in the fleet, at the
45	// moment nobody is watching it. They wait for their real anchor, which is due
46	// normally once the ledger has this run in it (#522).
47	export const FIRST_RUN_FREQUENCIES = ['hourly', 'daily-2h', 'daily-1h', 'daily', 'daily+1h'];
48	
49	// The documented anchor defaults (DESIGN §2) — applied when a repo omits
50	// `schedule` or any of its keys. This is the single source of these values; the
51	// checks layer's load-time range validation (engine/checks/helpers/repo-context.mjs)
52	// only bounds them, it does not re-declare them.
53	export const DEFAULT_SCHEDULE = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
54	
55	// Sun-indexed to match Date#getUTCDay (0 = Sunday). Also the canonical weekday
56	// vocabulary the config validator mirrors.
57	export const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
58	
59	// Hours the daily family offsets the anchor hour by (DESIGN §2).
60	const DAILY_OFFSETS = { 'daily-2h': -2, 'daily-1h': -1, daily: 0, 'daily+1h': 1 };
61	
62	const HOUR_MS = 3600 * 1000;
63	const DAY_MS = 24 * HOUR_MS;
64	const pad = (n) => String(n).padStart(2, '0');
65	const ymd = (d) => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
66	
67	// Last calendar day of a UTC month (day 0 of the next month rolls back).
68	const daysInMonth = (year, monthIndex) => new Date(Date.UTC(year, monthIndex + 1, 0)).getUTCDate();
69	
70	// Fill any absent key with its documented default; leave present values
71	// untouched (the checks layer has already range-validated them at load).
72	export function normalizeSchedule(schedule = {}) {
73	  const s = schedule || {};
74	  return {
75	    dailyHour: Number.isInteger(s.dailyHour) ? s.dailyHour : DEFAULT_SCHEDULE.dailyHour,
76	    weeklyDay: WEEKDAYS.includes(s.weeklyDay) ? s.weeklyDay : DEFAULT_SCHEDULE.weeklyDay,
77	    monthlyDay: Number.isInteger(s.monthlyDay) ? s.monthlyDay : DEFAULT_SCHEDULE.monthlyDay,
78	  };
79	}
80	
81	// The most-recent scheduled slot for one frequency at time `now`:
82	// `{ time: Date, id: string }` where `time` is the slot's UTC instant (≤ now)
83	// and `id` is the dispatch-issue slot id (DESIGN §4). `schedule` is assumed
84	// already normalized. `now` may be a Date or anything the Date ctor accepts.
85	export function mostRecentSlot(frequency, schedule, now) {
86	  const s = normalizeSchedule(schedule);
87	  now = new Date(now);
88	  const nowMs = now.getTime();
89	
90	  if (frequency === 'hourly') {
91	    // The top of the current hour — the poll never backfills a past hour.
92	    const time = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), now.getUTCHours()));
93	    return { time, id: `h${ymd(time)}T${pad(time.getUTCHours())}Z` };
94	  }
95	
96	  if (frequency in DAILY_OFFSETS) {
97	    const off = DAILY_OFFSETS[frequency];
98	    // Walk anchor DATES back from today until the slot instant is ≤ now. The id
99	    // keeps the ANCHOR date, so a `daily-2h` with dailyHour < 2 whose instant
100	    // lands on the previous calendar day still carries the anchor's date — the
101	    // wrap behavior of DESIGN §2 falls out for free.
102	    let anchor = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
103	    for (;;) {
104	      const time = new Date(anchor.getTime() + (s.dailyHour + off) * HOUR_MS);
105	      if (time.getTime() <= nowMs) return { time, id: `d${ymd(anchor)}` };
106	      anchor = new Date(anchor.getTime() - DAY_MS);
107	    }
108	  }
109	
110	  if (frequency === 'weekly') {
111	    const targetDow = WEEKDAYS.indexOf(s.weeklyDay);
112	    let date = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
113	    // Up to 8 steps guarantees the previous week's slot even when today is the
114	    // weekly day but earlier than dailyHour.
115	    for (let i = 0; i < 8; i += 1) {
116	      if (date.getUTCDay() === targetDow) {
117	        const time = new Date(date.getTime() + s.dailyHour * HOUR_MS);
118	        if (time.getTime() <= nowMs) return { time, id: `w${ymd(date)}` };
119	      }
120	      date = new Date(date.getTime() - DAY_MS);
121	    }
122	    // Unreachable in practice (a matching weekday always exists within 7 days).
123	    throw new Error(`no weekly slot resolved for ${s.weeklyDay}`);
124	  }
125	
126	  if (frequency === 'monthly') {
127	    let year = now.getUTCFullYear();
128	    let month = now.getUTCMonth();
129	    for (;;) {
130	      const day = Math.min(s.monthlyDay, daysInMonth(year, month)); // clamp to month length (DESIGN §2)
131	      const time = new Date(Date.UTC(year, month, day) + s.dailyHour * HOUR_MS);
132	      if (time.getTime() <= nowMs) return { time, id: `m${year}-${pad(month + 1)}` };
133	      month -= 1;
134	      if (month < 0) { month = 11; year -= 1; }
135	    }
136	  }
137	
138	  throw new Error(`unknown frequency "${frequency}"`);
139	}
140	
141	// The frequencies that are due right now, each with its slot id/time. `lastSuccess`
142	// is the last successful scheduler run's timestamp (Date / ISO string / null);
143	// null means "the ledger holds no prior success" → the FIRST_RUN_FREQUENCIES set
144	// is due. Unknown frequency tokens are ignored (never due) rather than thrown on.
145	export function dueSlots(frequencies, schedule, now, lastSuccess) {
146	  const s = normalizeSchedule(schedule);
147	  now = new Date(now);
148	  const nowMs = now.getTime();
149	  const tMs = lastSuccess === null || lastSuccess === undefined ? null : new Date(lastSuccess).getTime();
150	
151	  const out = [];
152	  for (const frequency of frequencies) {
153	    if (!FREQUENCIES.includes(frequency)) continue;
154	    const slot = mostRecentSlot(frequency, s, now);
155	    const t = slot.time.getTime();
156	    // `t <= nowMs` holds by construction; kept explicit as the stated contract.
157	    const due = tMs === null
158	      ? FIRST_RUN_FREQUENCIES.includes(frequency) && t <= nowMs
159	      : t > tMs && t <= nowMs;
160	    if (due) out.push({ frequency, slotId: slot.id, slotTime: slot.time.toISOString() });
161	  }
162	  return out;
163	}
164

