// Sun-indexed to match Date#getUTCDay (0 = Sunday). Also the canonical weekday
// vocabulary the config validator mirrors.
export const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

